import {DESTINIES,destiny,travelCost} from './destiny.js?v=0.9.0';
import {WORLD,PATHS,trialYears,timeSteps,totalAge,fateCost,canRewrite,rewriteDestiny,initWorld,title,ranks,entryReasons,enterImmortal,canTravel,travel,chooseDomain,requirements,breakthroughReasons,breakthrough,train,mission,worldEvent,resolveWorld} from './worlds.js?v=0.9.0';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
let chosenSpeed=30;
const scene=`<div class="cosmos-art" aria-hidden="true"><div class="cosmic-ring ring-one"></div><div class="cosmic-ring ring-two"></div><div class="cosmic-sun"></div><div class="cosmic-mountain back"></div><div class="cosmic-mountain front"></div><span>山海之外 · 诸天有序</span></div>`;
export function worldButton(){return '<button id="world-atlas" class="smallbtn">诸天万界 ↗</button>';}
export function worldPanel(s){const w=initWorld(s),reasons=entryReasons(s),c=WORLD.countries[w.country];return `<section class="card section world-entry"><span class="eyebrow">VOLUME VIII · 人间之后，诸天之上</span><h3>从一国山河，到多元宇宙</h3><p>100国 · 12星球 · 9宇宙<br>10级修仙 · 9级神阶 · 20神职</p><p class="sub">当前驻访：${esc(c.name)} · ${esc(c.land)}<br>已踏访 ${w.visitedCountries.length} 国 · 外交功德 ${w.virtue}</p><div class="tools"><button id="world-open" class="smallbtn">打开诸天图鉴</button><button id="world-mission" ${s.ended||s.pending||s.transition||s.familyChoice||s.stage!=='work'||w.pending||w.cycle>=Math.floor(s.day/365)?'disabled':''}>本岁外交历练</button></div>${w.pending?'<button id="world-pending" class="primary">继续外交抉择</button>':''}<div class="divider"></div><p class="sub">${reasons.length?'入道条件：'+reasons.map(esc).join('；'):'机缘已至，可以辞别凡间，开启道历。'}</p><button id="world-enter" class="primary" ${reasons.length?'disabled':''}>启灵入道 →</button><p class="sub">入道消耗1仙值；凡间年龄与家族封存，后续按道历成长。可先导出人生存档。</p></section>`;}
function chronicle(s){return initWorld(s).chronicle.map(x=>'<div class="world-log">'+esc(x)+'</div>').join('')||'<p class="sub">天地初开，等待你留下足迹。</p>';}
export function worldScreen(s){const w=initWorld(s),g=requirements(s),e=worldEvent(s),reasons=breakthroughReasons(s),p=WORLD.planets[w.planet],u=WORLD.universes[w.universe];return `<div class="world-shell"><div class="title-row"><div><span class="eyebrow">THE QINGYUN COSMOS · 卷八</span><h1>${PATHS[w.path]}纪事 <span class="gold">·</span> ${esc(title(s))}</h1></div><div class="tools">${worldButton()}<button id="archive" class="smallbtn">凡间档案</button><button id="export" class="smallbtn">导出</button><button id="import" class="smallbtn">导入</button><button id="world-new" class="smallbtn">新的人生</button></div></div><section class="cosmos-hero">${scene}<div class="cosmos-copy"><span class="eyebrow">${esc(u.name)} / ${esc(p.name)}</span><h2>一念越山海，<br>万界入青云。</h2><p>${esc(s.name)} · 凡间${Math.floor(s.day/365)}岁封存<br>道历 ${Math.floor(w.days/365).toLocaleString()}年 ${w.days%365}日 · ${esc(WORLD.domains[w.domain]?.name||'尚未封神')} ${w.domain===null?'':'神'}</p><div class="cosmic-metrics"><span><b>${w.visitedCountries.length}</b>百国足迹</span><span><b>${w.visitedPlanets.length} / 12</b>星球</span><span><b>${w.visitedUniverses.length} / 9</b>宇宙</span></div></div></section>${w.expired?`<section class="ended"><h2>道寿已尽，万界留名。</h2><p>${esc(w.deathReason)} · 总年龄${Math.floor(totalAge(s)).toLocaleString()}岁。档案仍可导出。</p></section>`:''}<div class="world-layout"><section><article class="card section"><span class="eyebrow">五维相生 · 万法同源</span><div class="world-stats">${s.stats.map((x,i)=>`<span>${['德','智','体','美','劳'][i]} <b>${Math.floor(x).toLocaleString()}</b></span>`).join('')}</div><p class="sub">体为基础，劳为实践，德领方向，智赋能力，美养精神。凡间疾病与家族年岁不再推进；本篇的失误累积心劫，可通过修身与履职化解。</p></article>${e?`<article class="card section event-card"><span class="event-tag">道历关键抉择 · ${esc(e.source)}</span><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="choices">${e.options.map((x,i)=>`<button data-world-answer="${i}">${'ABC'[i]} · ${esc(x)}</button>`).join('')}</div></article>`:`<article class="card section"><span class="eyebrow">修行有时 · 史鉴问道</span><h2>以实践证道</h2><p class="sub">当前每${trialYears(s).toLocaleString()}年出现关键抉择；距下次约${Math.max(0,(w.nextTrialDay-w.days)/365).toLocaleString(undefined,{maximumFractionDigits:1})}年。快进会停在节点或寿元上限，减少修为与观察收益。</p><div class="world-actions">${['明德济世','研习法则','调息修身','观象造境','躬身履职'].map((n,i)=>`<button data-world-train="${i}" ${w.expired?'disabled':''}>${n}</button>`).join('')}</div><label>修行跨度<select id="world-speed">${timeSteps(s).map(v=>`<option value="${v}" ${chosenSpeed===v?'selected':''}>${v===1?'一天 · 完整观察':v===7?'一周 · 85%修为':v===30?'一月 · 68%修为':(v/365).toLocaleString()+'年 · 50%修为'}</option>`).join('')}</select></label></article>`}<article class="card section"><h2>诸天履历</h2><div class="world-chronicle">${chronicle(s)}</div></article></section><aside><article class="card section"><span class="eyebrow">寿元与天命</span><h2>寿元 ${w.lifespan.toLocaleString()}岁</h2><p>总年龄 ${Math.floor(totalAge(s)).toLocaleString()}岁 · 剩余约 ${Math.max(0,Math.floor(w.lifespan-totalAge(s))).toLocaleString()}岁</p><p class="sub">当前天命：${esc(destiny(s).name)}<br>${esc(destiny(s).text)}<br>命元 ${w.fatePoints} · 改命消耗 ${fateCost(s)}</p><button id="world-fate" ${canRewrite(s)?'':'disabled'}>逆天改命</button><p class="sub">飞升后解锁；史鉴正确与突破积累命元。不复活、不重掷已得属性。</p></article><article class="card section"><span class="eyebrow">境界突破</span><h2>${esc(title(s))}</h2><div class="rank-list">${ranks(w.path).map((x,i)=>`<div class="rank ${i===w.rank?'active':''}">${String(i+1).padStart(2,'0')} · ${esc(x)}${i<w.rank?' ✓':''}</div>`).join('')}</div><p>修为 ${Math.floor(w.power).toLocaleString()} / ${g.power.toLocaleString()}</p><div class="bar"><i style="width:${Math.min(100,w.power/g.power*100)}%"></i></div><p class="sub">功德 ${w.virtue}/${g.virtue} · 实践 ${w.practice}/${g.practice}<br>心劫 ${w.strain.toFixed(0)}/100</p>${w.path===1&&w.rank===9?'<label>封神职掌<select id="world-domain"><option value="">请选择神职</option>'+WORLD.domains.map((d,i)=>`<option value="${i}" ${w.domain===i?'selected':''}>${esc(d.name)}神 · ${esc(d.duty)}</option>`).join('')+'</select></label>':''}<p class="sub">${w.completed?'已达成多元共议结局，仍可继续游历。':reasons.length?reasons.map(esc).join('<br>'):'突破条件齐备。'}</p><button id="world-break" class="primary" ${reasons.length||w.completed?'disabled':''}>${w.path===4&&w.rank===3?'达成诸界共议':'突破境界 →'}</button></article><article class="card section"><h3>天地坐标</h3><p>${esc(u.name)} · ${esc(u.rule)}<br>${esc(p.name)} · ${esc(p.law)}</p><p class="sub">本地危机：${esc(p.hazard)}<br>神职责任：${esc(WORLD.domains[w.domain]?.duty||'修身与济世')}</p><button id="world-open" class="smallbtn">星图与界门 ↗</button></article><article class="card section"><h3>五部成长史</h3>${PATHS.map((p,i)=>`<p class="${w.path===i?'gold':'sub'}">${i<w.path?'✓':i===w.path?'◆':'○'} ${p}篇</p>`).join('')}<p class="sub">至高神仍在一个宇宙内。成为宇宙之主后才开启多元宇宙。所有规则均为架空设定。</p></article></aside></div></div>`;}
export function bindWorld(s,{modal,save,render,toast,archive,exportSave,importSave,newLife,signal}){const commit=()=>{save();render();};if($('#world-fate'))$('#world-fate').onclick=()=>{modal('<h2>逆天改命</h2><p>消耗'+fateCost(s)+'命元，更换此后成长方向；再次改命消耗递增。</p><div class="choices">'+DESTINIES.filter(d=>d.id!==(s.destiny||'ordinary')).map(d=>'<button data-fate="'+d.id+'">'+esc(d.name)+' · '+esc(d.text)+'</button>').join('')+'</div>');document.querySelectorAll('[data-fate]').forEach(b=>b.onclick=()=>{if(rewriteDestiny(s,b.dataset.fate)){document.querySelector('#close-dialog').click();commit();toast('天命已改，往后的路由你重写。');}});};const atlas=()=>openAtlas(s,{modal,commit,toast});for(const id of ['world-atlas','world-open'])if($('#'+id))$('#'+id).onclick=atlas;if($('#world-enter'))$('#world-enter').onclick=()=>{modal('<h2>辞别凡间，启灵入道</h2><p>消耗1仙值，保留此刻的凡间履历、任职与家族快照。道历独立推进，开启修仙、封神和诸天探索；此存档不再返回凡间时间线。</p><button id="world-backup">先导出存档</button> <button id="world-confirm" class="primary">确认启灵入道</button>');$('#world-backup').onclick=exportSave;$('#world-confirm').onclick=()=>{if(enterImmortal(s)){document.querySelector('#close-dialog').click();commit();signal();toast('启灵入道，道历开启。');}};};const showDecision=()=>{const e=worldEvent(s);if(!e)return;modal(`<span class="eyebrow">外交历练 · ${esc(WORLD.countries[s.world.country].name)}</span><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="choices">${e.options.map((x,i)=>`<button data-world-answer="${i}">${esc(x)}</button>`).join('')}</div>`);bindAnswers();};if($('#world-mission'))$('#world-mission').onclick=()=>{if(mission(s)){commit();showDecision();}};for(const id of ['world-pending','world-pending-top'])if($('#'+id))$('#'+id).onclick=showDecision;function bindAnswers(){document.querySelectorAll('[data-world-answer]').forEach(b=>b.onclick=()=>{const r=resolveWorld(s,+b.dataset.worldAnswer);if(!r)return;commit();modal(`<span class="eyebrow">历练回顾</span><h2>${r.ok?'问道有得':'心劫未平'}</h2><p>${esc(r.choice)}</p><p>${esc(r.explanation)}</p><p class="sub">史实：${esc(r.historySource.fact)}</p><a href="${esc(r.historySource.url)}" target="_blank" rel="noreferrer">查看史实出处 ↗</a><p>${r.ok?'功德+3 · 修为+80 · 实践+1'+(s.world.path>0?' · 命元+1':''):'修为-30（最低0） · 心劫+18 · 实践+1'}</p>`);});}bindAnswers();document.querySelectorAll('[data-world-train]').forEach(b=>b.onclick=()=>{chosenSpeed=+$('#world-speed').value;const n=train(s,chosenSpeed,+b.dataset.worldTrain);commit();toast(`修行${n}日${s.world.pending?'，年度问道已开启':''}`);});if($('#world-domain'))$('#world-domain').onchange=()=>{if($('#world-domain').value!==''&&chooseDomain(s,+$('#world-domain').value))commit();};if($('#world-break'))$('#world-break').onclick=()=>{if(breakthrough(s)){commit();signal();modal(`<span class="eyebrow">境界喜报</span><h2>${esc(title(s))}</h2>${scene}<p>${s.world.completed?'诸界共议已成，星门仍为你敞开。':'以五维为根，以实践为路。新的天地已经展开。'}</p>`);}};if(s.world.path>0){$('#archive').onclick=archive;$('#export').onclick=exportSave;$('#import').onclick=importSave;$('#world-new').onclick=newLife;}}
export function openAtlas(s,{modal,commit=()=>{},toast=()=>{}}){let tab='country',page=0,query='';const render=()=>{const w=s?initWorld(s):null;const all=tab==='country'?WORLD.countries:tab==='planet'?WORLD.planets:WORLD.universes;const found=all.filter(x=>(x.name+(x.polity||x.law||x.rule||'')+(x.economy||'')).includes(query));page=Math.max(0,Math.min(page,Math.ceil(found.length/12)-1));modal(`<div class="atlas-heading"><span class="eyebrow">ATLAS OF TEN THOUSAND REALMS</span><h2>诸天万界 · 山海星图</h2><p>100国 / 12星球 / 9宇宙 · 27境界 / 20神职</p></div>${scene}<div class="atlas-tabs">${[['country','百国'],['planet','星球'],['universe','宇宙']].map(([id,n])=>`<button data-atlas="${id}" aria-pressed="${tab===id}">${n}</button>`).join('')}<button id="atlas-lore">境界与来源</button></div><label>检索${tab==='country'?'国家、政体或产业':'世界'}<input id="atlas-search" value="${esc(query)}" placeholder="输入名称或特色"></label><p class="sub">${!w?'创建角色后可记录足迹。':tab==='country'?'18岁任职后可出访，每岁一次外交历练；不改变原籍官职。':tab==='planet'?'封神后开放星球航路，穿行消耗'+travelCost(s)+'修为。':'宇宙之主之后，开启多元界门，穿行消耗'+travelCost(s)+'修为。'} 共${found.length}项 · 第${page+1}/${Math.max(1,Math.ceil(found.length/12))}页</p><div class="atlas-grid">${found.slice(page*12,page*12+12).map(x=>{const selected=w&&(tab==='country'?w.country:tab==='planet'?w.planet:w.universe)===x.id;const can=w&&canTravel(s,tab,x.id);return `<article class="atlas-card"><span class="atlas-number">${String(x.id+1).padStart(3,'0')} / ${tab==='country'?'NATION':tab==='planet'?'PLANET':'UNIVERSE'}</span><h3>${esc(x.name)} ${selected?'<small>◆ 当前</small>':''}</h3><p>${esc(x.polity||x.law||x.rule)}</p><p class="sub">${tab==='country'?esc(x.land)+' · '+esc(x.economy)+'<br>人口 '+(x.population/1e8).toFixed(2)+'亿<br>'+esc(x.checks)+'<br>危机：'+esc(x.crisis)+'<br>政策线索：'+esc(x.response):tab==='planet'?'本地危机：'+esc(x.hazard):'与本宇宙法则差异，影响历练情境与观测'}</p>${w?`<button data-travel="${x.id}" ${can?'':'disabled'}>${selected?'已在此地':can?'启程 →':'尚未满足航行条件'}</button>`:''}</article>`;}).join('')}</div><div class="row"><button id="atlas-prev" ${page===0?'disabled':''}>上一页</button><button id="atlas-next" ${(page+1)*12>=found.length?'disabled':''}>下一页</button></div>`);document.querySelectorAll('[data-atlas]').forEach(b=>b.onclick=()=>{tab=b.dataset.atlas;page=0;query='';render();});$('#atlas-search').onchange=()=>{query=$('#atlas-search').value.trim();page=0;render();};$('#atlas-prev').onclick=()=>{page--;render();};$('#atlas-next').onclick=()=>{page++;render();};document.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>{if(travel(s,tab,+b.dataset.travel)){commit();render();toast('已记录新的诸天足迹');}});$('#atlas-lore').onclick=()=>{modal(`<span class="eyebrow">世界设定与素材来源</span><h2>从凡尘至诸界共议</h2>${[WORLD.immortals,WORLD.gods,WORLD.cosmic,WORLD.multiverse].map((xs,i)=>'<h3>'+['修仙十境','神阶九重','单宇宙四阶','多元宇宙四阶'][i]+'</h3><p>'+xs.map(esc).join(' → ')+'</p>').join('')}<h3>二十神职</h3><p>${WORLD.domains.map(x=>esc(x.name)+'神（'+esc(x.duty)+'）').join('、')}</p><p>等级、神职、百国框架采用素材库原创草案；游戏事件及数值为本版原创。四部古籍《抱朴子》《山海经》《搜神记》《周礼》作为修行、神话及制度研究方向，不将神话当作史实，也不将科普假说当作已证实的修仙规律。</p><p class="sub">草案版本：${esc(WORLD.provenance.revision||WORLD.revision)}<br>策划审核：${esc(WORLD.provenance.reviewed)}<br>原始设计SHA-256：${esc(WORLD.provenance.sha256)}</p><button id="atlas-return">返回星图</button>`);$('#atlas-return').onclick=render;};};render();}
